        "code": "class LoaiNacFactory : MonAnFactory\n    {\n        public HuTieu LayToHuTieu()\n        {\n            return new HuTieuNac();\n        }\n\n        public My LayToMy()\n        {\n            return new MyNac();\n        }\n    }"
