    "example": "// - Khai báo visitor interface với một tập hợp các phương thức \"truy cập\", một phương thức cho mỗi lớp phần tử cụ thể tồn tại trong chương trình.\npublic interface IComponent\n    {\n        void Accept(IVisitor visitor);\n    }\n\n    public class ConcreteComponentA : IComponent\n    {\n        public void Accept(IVisitor visitor)\n        {\n            visitor.VisitConcreteComponentA(this);\n        }\n\n        public string ExclusiveMethodOfConcreteComponentA()\n        {\n            return \"A\";\n        }\n    }\n\n    public class ConcreteComponentB : IComponent\n    {\n        public void Accept(IVisitor visitor)\n        {\n            visitor.VisitConcreteComponentB(this);\n        }\n\n        public string SpecialMethodOfConcreteComponentB()\n        {\n            return \"B\";\n        }\n    }\n\n    public interface IVisitor\n    {\n        void VisitConcreteComponentA(ConcreteComponentA element);\n\n        void VisitConcreteComponentB(ConcreteComponentB element);\n    }\n\n    class ConcreteVisitor1 : IVisitor\n    {\n        public void VisitConcreteComponentA(ConcreteComponentA element)\n        {\n            Console.WriteLine(element.ExclusiveMethodOfConcreteComponentA() + \" + ConcreteVisitor1\");\n        }\n\n        public void VisitConcreteComponentB(ConcreteComponentB element)\n        {\n            Console.WriteLine(element.SpecialMethodOfConcreteComponentB() + \" + ConcreteVisitor1\");\n        }\n    }\n\n    class ConcreteVisitor2 : IVisitor\n    {\n        public void VisitConcreteComponentA(ConcreteComponentA element)\n        {\n            Console.WriteLine(element.ExclusiveMethodOfConcreteComponentA() + \" + ConcreteVisitor2\");\n        }\n\n        public void VisitConcreteComponentB(ConcreteComponentB element)\n        {\n            Console.WriteLine(element.SpecialMethodOfConcreteComponentB() + \" + ConcreteVisitor2\");\n        }\n    }\n\n    public class Client\n    {\n        public static void ClientCode(List components, IVisitor visitor)\n        {\n            foreach (var component in components)\n            {\n                component.Accept(visitor);\n            }\n        }\n    }\n\n    class Program\n    {\n        static void Main(string[] args)\n        {\n            List components = new List\n            {\n                new ConcreteComponentA(),\n                new ConcreteComponentB()\n            };\n\n            Console.WriteLine(\"The client code works with all visitors via the base Visitor interface:\");\n            var visitor1 = new ConcreteVisitor1();\n            Client.ClientCode(components, visitor1);\n\n            Console.WriteLine();\n\n            Console.WriteLine(\"It allows the same client code to work with different types of visitors:\");\n            var visitor2 = new ConcreteVisitor2();\n            Client.ClientCode(components, visitor2);\n        }\n    }",
    "related": "- Có thể xem Visitor là một phiên bản hiệu quả của Command. Các đối tượng của nó có thể thực thi các operation trên các đối tượng khác nhau của các lớp khác nhau.\n\n- Có thể sử dụng Visitor để thực hiện một thao tác trên toàn bộ cây Composite.\n\n- Có thể sử dụng Visitor cùng với Iterator để duyệt qua một cấu trúc dữ liệu phức tạp và thực hiện một số thao tác trên các phần tử của nó, ngay cả khi tất cả chúng đều có các lớp khác nhau."
